HANDLE hProcess = CreateProcessA("C:\\Windows\\System32\\svchost.exe", ...);
WriteProcessMemory(hProcess, remoteAddress, maliciousPayload, payloadSize, ...);
CreateRemoteThread(hProcess, NULL, 0, remoteAddress, NULL, 0, NULL);

